SELECT p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, a.admittime, a.dischtime, a.deathtime, s.los, s.in_hospital_mortality_rate, s.readmission_30_days_rate, m.medication_complexity_score, t.tertile, row_number() OVER(PARTITION BY t.tertile ORDER BY m.medication_complexity_score DESC) AS rank_within_tertile FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN stay s ON a.stay_id = s.stay_id JOIN emar m ON m.subject_id = p.subject_id AND m.hadm_id = a.hadm_id JOIN (SELECT subject_id, hadm_id, tertile FROM patients WHERE gender = 'F' AND anchor_year_group BETWEEN 71 AND 81) AS t ON t.subject_id = p.subject_id AND t.hadm_id = a.hadm_id WHERE p.gender = 'F' AND p.anchor_age = 76 AND p.anchor_year = 2019 AND p.anchor_year_group BETWEEN 71 AND 81 AND a.admittime BETWEEN 0 AND 72;